var $BottomScreen = screen("DashBoard", 0)
var $TopScreen = screen("DashBoard", 5)
timer interval 0
	var $Alt = input_number("Alt", 0)-6203007
	var $Speed = input_number("VLS", 0)
	var $VSpeed = input_number("VLS", 3)
	var $Charge = input_number("Battery", 2)
	var $Mass = input_number("Phys", 1)
	var $BatteryRem = text("{0.00}", -((120000*input_number("Battery", 2))/input_number("Battery", 3))*60)
	$BottomScreen.blank(black)
	$TopScreen.blank(black)
	$BottomScreen.write(5, 10, white, text("Alt: {0}", $Alt))
	$BottomScreen.write(5, 20, white, text("Speed: {0}m/s", $Speed))
	$BottomScreen.write(5, 30, white, text("VSpeed: {0}m/s", $VSpeed))
	$TopScreen.write(5, 10, white, text("Charge {0}%", $Charge*100))
	$TopScreen.write(5, 20, white, text("Mass {0} Kg", $Mass))
	$TopScreen.write(5, 30, white, text("Empty {0.0} Min", $BatteryRem))

include "ColorOreScanner.main.xc"
init
	print("Boot BIOS, load Ore scanner.")
	@oreinit()
	@SetOreScreen(screen(0,0)) ; optional. If you don't use this the scanner uses screen(0,0)
